// Contains Duplicate - Check if any value appears at least twice
var table = AnimatedHashTable<Int, Bool>()
let nums = [1, 2, 3, 1]

func hasDuplicates(_ list: [Int], t: inout AnimatedHashTable<Int, Bool>) -> Bool {
    for num in list {
        if t.get(num) == true {
            return true
        }
        t.put(num, true)
    }
    return false
}

let duplicateResult = hasDuplicates(nums, t: &table)
